def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Each adjacent diagonal pair defines a complete diagonal ray/line of its color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                if 0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == color:
                    for sign in (-1, 1):
                        rr, cc = r, c
                        while 0 <= rr < h and 0 <= cc < w:
                            if grid[rr][cc] == bg:
                                out[rr][cc] = color
                            rr += sign*dr
                            cc += sign*dc
    return out
